async def wait_for_es(
    es: AsyncElasticsearch,
    attempts: int = 30,
) -> None:
    last_error: Exception | None = None

    for _ in range(attempts):
        try:
            if await es.ping():
                return
        except Exception as exc: # noqa: BLE001
            last_error = exc

        await asyncio.sleep(1)

    if last_error:
        raise RuntimeError(
            "Elasticsearch did not become ready"
        ) from last_error

    raise RuntimeError(
        "Elasticsearch did not become ready"
    )


