async def search_payments(
    es: AsyncElasticsearch,
    query_text: str | None,
    status: str | None,
    merchant_id: str | None,
    page: int,
    size: int,
) -> dict[str, Any]:
    if query_text:
        query_clause = {
            "bool": {
                "should": [
                    {
                        "term": {
                            "payment_id": {
                                "value": query_text,
                                "boost": 10,
                            }
                        }
                    },
                    {
                        "multi_match": {
                            "query": query_text,
                            "fields": [
                                "payment_id^5",
                                "order_id^4",
                                "booking_id^4",
                                "cart_id^3",
                                "customer_id^3",
                                "merchant_id^3",
                                "status^2",
                                "currency",
                                "description",
                            ],
                        }
                    },
                ],
                "minimum_should_match": 1,
            }
        }
    else:
        query_clause = {
            "match_all": {},
        }

    filters: list[dict[str, Any]] = []

    if status:
        filters.append(
            {
                "term": {
                    "status": status,
                }
            }
        )

    if merchant_id:
        filters.append(
            {
                "term": {
                    "merchant_id": merchant_id,
                }
            }
        )

    response = await es.search(
        index=PAYMENTS_INDEX,
        query={
            "bool": {
                "must": [query_clause],
                "filter": filters,
            }
        },
        from_=(page - 1) * size,
        size=size,
        sort=[
            {
                "updated_at": {
                    "order": "desc",
                    "missing": "_last",
                }
            }
        ],
    )

    body = _response_body(response)
    hits = body.get("hits", {})
    total = hits.get("total", 0)

    if isinstance(total, Mapping):
        total = total.get("value", 0)

    items = []

    for hit in hits.get("hits", []):
        source = hit.get("_source", {})

        items.append(
            {
                "id": hit.get("_id"),
                **source,
            }
        )

    return {
        "index": PAYMENTS_INDEX,
        "total": int(total),
        "page": page,
        "size": size,
        "items": items,
    }
